nums = [1, 2, 3, 4, 5, 6]
squares = [n * n for n in nums]
evens = [n for n in nums if n % 2 == 0]
lengths = {w: len(w) for w in ["sun", "moon"]}
unique = {n % 3 for n in nums}

print(squares)     # [1, 4, 9, 16, 25, 36]
print(evens)       # [2, 4, 6]
print(lengths)     # {'sun': 3, 'moon': 4}
print(unique)      # {0, 1, 2}
